-- Simplified Normalized Course Registration Model

-- Students Table
CREATE TABLE Students (
    StudentID INT PRIMARY KEY,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Email VARCHAR(100) UNIQUE NOT NULL,
    EnrollmentDate DATE NOT NULL
);

-- Courses Table
CREATE TABLE Courses (
    CourseID INT PRIMARY KEY,
    CourseName VARCHAR(100) NOT NULL,
    Credits INT NOT NULL,
    Department VARCHAR(50) NOT NULL
);

-- Instructors Table
CREATE TABLE Instructors (
    InstructorID INT PRIMARY KEY,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Email VARCHAR(100) UNIQUE NOT NULL,
    Department VARCHAR(50) NOT NULL
);

-- Semesters Table
CREATE TABLE Semesters (
    SemesterID INT PRIMARY KEY,
    Semester VARCHAR(20) NOT NULL,
    Year INT NOT NULL
);

-- Course Offerings Table (Simplified: No separate mappings)
CREATE TABLE CourseOfferings (
    OfferingID INT PRIMARY KEY,
    CourseID INT NOT NULL,
    InstructorID INT NOT NULL,
    SemesterID INT NOT NULL,
    Schedule VARCHAR(50) NOT NULL,
    RoomNumber VARCHAR(20) NOT NULL,
    FOREIGN KEY (CourseID) REFERENCES Courses(CourseID),
    FOREIGN KEY (InstructorID) REFERENCES Instructors(InstructorID),
    FOREIGN KEY (SemesterID) REFERENCES Semesters(SemesterID)
);

-- Registrations Table (Directly uses the IDs from normalized schema)
CREATE TABLE Registrations (
    RegistrationID INT PRIMARY KEY,
    StudentID INT NOT NULL,
    OfferingID INT NOT NULL,
    RegistrationDate DATE NOT NULL,
    Grade VARCHAR(5),
    FOREIGN KEY (StudentID) REFERENCES Students(StudentID),
    FOREIGN KEY (OfferingID) REFERENCES CourseOfferings(OfferingID)
);

